type CreateAviRouteSpec struct {
	// Specify the name of a particular network profile that the virtual service
	//   will be associated with.
	//
	//   Avi provides the following profiles by default:
	//
	//   - System-TCP-Fast-Path
	//   - System-TCP-Proxy
	//   - System-UDP-Fast-Path
	//   - System-UDP-Fast-Path-VDI
	//   - System-UDP-No-SNAT
	//   - System-UDP-Per-Pkt
	//
	//   You can also use profiles that were created by yourself. Be sure it matches
	//   the value of `protocol`.
	NetworkProfile *string `json:"networkProfile"`
	// The load balancing algorithm will pick a server within the pool’s list of
	//   available servers. Values `LB_ALGORITHM_NEAREST_SERVER` and
	//   `LB_ALGORITHM_TOPOLOGY` are only allowed for GSLB pool (for this, they are
	//   never used).
	//
	//   Enum options:
	//
	//   - LB_ALGORITHM_LEAST_CONNECTIONS
	//   - LB_ALGORITHM_ROUND_ROBIN
	//   - LB_ALGORITHM_FASTEST_RESPONSE
	//   - LB_ALGORITHM_CONSISTENT_HASH
	//   - LB_ALGORITHM_LEAST_LOAD
	//   - LB_ALGORITHM_FEWEST_SERVERS
	//   - LB_ALGORITHM_RANDOM
	//   - LB_ALGORITHM_FEWEST_TASKS
	//   - LB_ALGORITHM_NEAREST_SERVER
	//   - LB_ALGORITHM_CORE_AFFINITY
	//   - LB_ALGORITHM_TOPOLOGY
	LbAlgorithm *string `json:"lbAlgorithm"`
	// Criteria used as a key for determining the hash between the client and
	//   server. User can specify this value only if `lbAlgorithm` is set to
	//   `LB_ALGORITHM_CONSISTENT_HASH`.
	//
	//   Enum options:
	//
	//   - LB_ALGORITHM_CONSISTENT_HASH_SOURCE_IP_ADDRESS
	//   - LB_ALGORITHM_CONSISTENT_HASH_SOURCE_IP_ADDRESS_AND_PORT
	//   - LB_ALGORITHM_CONSISTENT_HASH_URI
	//   - LB_ALGORITHM_CONSISTENT_HASH_CUSTOM_HEADER
	//   - LB_ALGORITHM_CONSISTENT_HASH_CUSTOM_STRING
	//   - LB_ALGORITHM_CONSISTENT_HASH_CALLID
	LbAlgorithmHash *string `json:"lbAlgorithmHash"`
	// HTTP header name to be used for the hash key. Required when
	//   `lbAlgorithmHash` is set to `LB_ALGORITHM_CONSISTENT_HASH_CUSTOM_HEADER`.
	LbAlgorithmConsistentHashHeader *string `json:"lbAlgorithmConsistentHashHeader"`
	// name of a VsVIP to allocate.
	//
	//   This field is used for allocating existed VsVIP to a route.
	//
	//   If `vsVip` is specified, the `preferedNetwork` on its LoadBalancer will
	//   be ignored.
	VsVip *string `json:"vsVip"`
	// a route's VsVIP being `persistent` means it will not be removed from
	//   AVI even after the route is deleted.
	PersistentVsVip *bool `json:"persistentVsVIP"`
}

